import griffe


class AppendCheckedExtension(griffe.Extension):
    """Griffe extension: append ' [checked]' to every collected function's docstring."""

    def on_function_instance(
        self,
        node,
        func: griffe.Function,
        agent: griffe.Visitor | griffe.Inspector,
        **kwargs,
    ) -> None:
        if func.docstring is not None:
            func.docstring.value += " [checked]"
        else:
            func.docstring = griffe.Docstring(" [checked]", parent=func)


